  if(!model)return;const i=Number(el('time').value);if(!Number.isInteger(i)||i<0||i>=model.frames.length){clear();el('status').textContent='AFVIST: sample_index';return;}
  const f=model.frames[i],g=el('figure'),chart=el('chart');g.replaceChildren();chart.replaceChildren();el('angles').replaceChildren();
  const extent=Math.max(model.image.width,model.image.height);
  const fit=Math.max((model.image.width/extent)/420,(model.image.height/extent)/350);
  const x=p=>30+(p.x/extent)/fit,y=p=>25+(p.y/extent)/fit;
  const edges=[['toe','ankle'],['ankle','knee'],['knee','hip'],['hip','shoulder'],['shoulder','elbow'],['elbow','wrist']];
  for(const [a,b] of edges)add(g,'line',{x1:x(f.points[a]),y1:y(f.points[a]),x2:x(f.points[b]),y2:y(f.points[b]),stroke:'#123944','stroke-width':5});
  for(const [name,p] of Object.entries(f.points)){add(g,'circle',{cx:x(p),cy:y(p),r:5,fill:'#087e8b'});add(g,'text',{x:x(p)+7,y:y(p)-7,'font-size':12},name);}
  // This full-width guide depicts only measured y, never an invented bar x.
  const barY=y({y:f.bar_y_px});
  add(g,'line',{x1:20,y1:barY,x2:460,y2:barY,stroke:'#b14714','stroke-dasharray':'6 5','stroke-width':2});
  add(g,'text',{x:22,y:barY-5,'font-size':12,fill:'#8b350e'},'Stangens y (x ukendt)');
  el('frame').textContent='Sample '+i+' · '+f.t_s+' s · '+(f.phase||'mellem fasemarkører')+' · '+f.bar_relative_up_cm.toFixed(2)+' cm fra første sample (op +).';
