  add(chart,'line',{x1:40,y1:110,x2:700,y2:110,stroke:'#9caeb2'});
  add(chart,'polyline',{points:fs.map(q=>tx(q.t_s)+','+cy(q.bar_relative_up_cm)).join(' '),fill:'none',stroke:'#b14714','stroke-width':3});
  for(const q of fs)add(chart,'circle',{cx:tx(q.t_s),cy:cy(q.bar_relative_up_cm),r:4,fill:'#b14714'});
  for(const p of model.phases){const px=tx(p.t_s);add(chart,'line',{x1:px,y1:15,x2:px,y2:195,stroke:'#087e8b','stroke-dasharray':'3 4'});add(chart,'text',{x:px,y:215,'text-anchor':'middle','font-size':11},p.name);}
  add(chart,'circle',{cx:tx(f.t_s),cy:cy(f.bar_relative_up_cm),r:8,fill:'none',stroke:'#123944','stroke-width':3});
  add(chart,'text',{x:40,y:240,'font-size':12},t0+' s → '+fs[fs.length-1].t_s+' s · op + · lodret skala ±'+max.toFixed(2)+' cm');
